exercises.solution:
const passagem = 5.2;
const viagens = 3;

const gasto = passagem * viagens;
const gastoNaTela = gasto.toFixed(2);
const passouDe15 = gasto > 15;

console.log('Gasto:', gastoNaTela);
console.log('gasto:', typeof gasto);
console.log('gastoNaTela:', typeof gastoNaTela);
console.log('passouDe15:', typeof passouDe15);

